package com.bharatsecure.app

import android.media.AudioManager
import android.media.ToneGenerator
import android.util.Log
import kotlin.concurrent.thread

/**
 * The scam alarm beep.
 *
 * A scam warning used to be silent - a vibration and a notification - which is
 * easy to miss while the phone is at your ear or lying on speaker. This plays a
 * short run of loud beeps the moment the detector flags the call, so the user
 * looks at the screen while the scammer is still talking.
 *
 * The tone is generated by Android (ToneGenerator): there is no audio file to
 * ship and it needs no network. It goes out on the alarm stream so it is heard
 * over the call audio, and it only plays out of this phone's speaker - the call
 * itself is never touched, muted or cut.
 */
object ScamBeep {
    private const val TAG = "ScamBeep"

    private const val BEEPS = 3
    private const val BEEP_MS = 350
    private const val GAP_MS = 150L
    private const val VOLUME = 100 // ToneGenerator takes 0..100

    /** Don't start again while the last run is still ringing in the user's ear. */
    private const val MIN_GAP_MS = 6_000L

    private val lock = Any()
    private var lastAtMs = 0L

    /**
     * Plays the alarm, at most once every [MIN_GAP_MS]. Returns at once: the
     * tone runs on its own thread, so the recording loop is never held up.
     */
    fun alarm() {
        synchronized(lock) {
            val now = System.currentTimeMillis()
            if (now - lastAtMs < MIN_GAP_MS) return
            lastAtMs = now
        }
        thread(name = "scam-beep", isDaemon = true) {
            var tone: ToneGenerator? = null
            try {
                tone = ToneGenerator(AudioManager.STREAM_ALARM, VOLUME)
                repeat(BEEPS) {
                    // The alert tone isn't on every phone; fall back to a plain beep.
                    if (!tone.startTone(ToneGenerator.TONE_CDMA_ABBR_ALERT, BEEP_MS)) {
                        tone.startTone(ToneGenerator.TONE_PROP_BEEP2, BEEP_MS)
                    }
                    Thread.sleep(BEEP_MS + GAP_MS)
                }
            } catch (e: Exception) {
                // A phone that won't give us a tone generator must not take the
                // warning down with it: the notification and vibration still run.
                Log.w(TAG, "could not play the scam alarm", e)
            } finally {
                runCatching { tone?.release() }
            }
        }
    }
}
